//   generator  C:/Users/jimbo/tegriddy-worktrees/_b_vectors/main.rs (outside the repo),
//              sha256 6607a19a4a5ce2b5e172eb7cee4cc1df87dd7d5dde5bed57893765f5b34a03aa
